//! (eval-rules-8) `reach` (in `coherence`): a shadow covers what its
//! props ask at the frame's scale.
//!
//! A shadow is CSS's `box-shadow` (design.md `elevation` tokens, `0 8px
//! 24px $shadow.alpha(0.3)`; spec.md 6.6: shadow lists spring): the box
//! that casts it, moved by its offset and grown by its spread, blurred
//! by a Gaussian whose standard deviation is half its blur radius (CSS
//! Backgrounds 3, "the resulting shadow must approximate the image that
//! would be generated by applying to the shadow a Gaussian blur with a
//! standard deviation equal to half the blur radius"). Every length of it
//! is a logical px, so on a screen of scale `s` each is `s` device px.
//! The renderer clips each shadow to the area it may cover (`extent`,
//! what its damage and its buffer's overhang are worked out from), so on
//! every frame, from what the props asked that frame (springs applied,
//! from strand-render's `eval-hooks`) and the box it was cast by, the
//! check holds, in device px:
//!
//! - its area is centred on the cast box moved by `(x, y) × s`;
//! - it reaches past the cast box grown by `spread × s` at least as far
//!   as the blurred edge still shows: where `alpha × (1 − Φ(d / σ))`, the
//!   edge of a box blurred by `σ = blur × s / 2` at `d` past it, falls
//!   under half a step of 1/255 (so a cut there is no step the eye sees);
//! - and no further than `4σ` and two pixels' rounding: past that the
//!   Gaussian's tail is below 1/255 at any alpha, so a wider area is a
//!   blur wider than asked.
//!
//! Worked out by the check from the asked values alone, never by the
//! flattener's own reach. Held-out set I's blur-ignores-scale drew every
//! shadow at a scale of 1.5 or 2 with the blur of scale 1, which only
//! references saw.

use super::{Cx, Finding};
use crate::scenario::CheckId;
use crate::trace::QUANTUM;

/// `1 − Φ(z)`, the standard normal's upper tail (Abramowitz and Stegun
/// 7.1.26 for `erfc`, absolute error under 1.5e-7).
pub fn tail(z: f64) -> f64 {
    let x = z / std::f64::consts::SQRT_2;
    let (s, x) = if x < 0.0 { (-1.0, -x) } else { (1.0, x) };
    let t = 1.0 / (1.0 + 0.327_591_1 * x);
    let poly = t
        * (0.254_829_592
            + t * (-0.284_496_736
                + t * (1.421_413_741 + t * (-1.453_152_027 + t * 1.061_405_429))));
    let erfc = poly * (-x * x).exp();
    if s > 0.0 {
        0.5 * erfc
    } else {
        1.0 - 0.5 * erfc
    }
}

/// How many standard deviations past a blurred edge a shadow of `alpha`
/// still draws at least half a step of 1/255: 0 when it never does.
pub fn visible_z(alpha: f64) -> f64 {
    let floor = 0.5 / 255.0;
    if alpha <= floor {
        return 0.0;
    }
    let (mut lo, mut hi) = (0.0f64, 10.0f64);
    for _ in 0..60 {
        let mid = 0.5 * (lo + hi);
        if alpha * tail(mid) > floor {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    lo
}

pub fn run(cx: &Cx) -> Vec<Finding> {
    let mut out = Vec::new();
    let mut judged = 0u64;
    let seg_name = |k: u32| {
        cx.trace
            .segments
            .iter()
            .rev()
            .find(|s| s.s.is_none_or(|s| s < k) && k <= s.e)
            .map(|s| s.name.clone())
            .unwrap_or_default()
    };
    for f in &cx.trace.frames {
        let s = cx.trace.scale_at(f);
        for sh in &f.shadows {
            if sh.a <= 0.0 || cx.allowed(CheckId::Coherence, &sh.key) {
                continue;
            }
            let [x, y, blur, spread] = sh.asked.map(f64::from);
            if !(blur.is_finite() && x.is_finite() && y.is_finite() && spread.is_finite()) {
                continue;
            }
            let d = |v: f32| f64::from(v) * s;
            let (fx, fy, fw, fh) = (
                d(sh.frame[0]),
                d(sh.frame[1]),
                d(sh.frame[2]),
                d(sh.frame[3]),
            );
            let (ex, ey, ew, eh) = (
                d(sh.extent[0]),
                d(sh.extent[1]),
                d(sh.extent[2]),
                d(sh.extent[3]),
            );
            judged += 1;
            // The recorded boxes are within a quantum of what was drawn,
            // on each edge, and the cast box is snapped to device px.
            let give = 4.0 * QUANTUM * s + 0.05;
            let sigma = blur.max(0.0) * s / 2.0;
            let lo = sigma * visible_z(f64::from(sh.a));
            let hi = 4.0 * sigma + 2.0;
            let mut bad: Option<String> = None;
            for (axis, centre, want, half, cast) in [
                (
                    "x",
                    ex + ew / 2.0 - (fx + fw / 2.0),
                    x * s,
                    ew / 2.0,
                    fw / 2.0,
                ),
                (
                    "y",
                    ey + eh / 2.0 - (fy + fh / 2.0),
                    y * s,
                    eh / 2.0,
                    fh / 2.0,
                ),
            ] {
                if (centre - want).abs() > give {
                    bad = Some(format!(
                        "its area is centred {centre:.2} device px from its box's centre on \
                         {axis}, where its offset of {:.2} at scale {s} puts it {want:.2}",
                        want / s
                    ));
                    break;
                }
                let reach = half - cast - spread * s;
                if reach < lo - give {
                    bad = Some(format!(
                        "it reaches {reach:.2} device px past its box grown by its spread on \
                         {axis}, short of the {lo:.2} px where its blur still shows (blur {blur} \
                         at scale {s} is σ {sigma:.2} device px, alpha {:.2}): the shadow is cut",
                        sh.a
                    ));
                    break;
                }
                if reach > hi + give {
                    bad = Some(format!(
                        "it reaches {reach:.2} device px past its box grown by its spread on \
                         {axis}, past the {hi:.2} px a blur of {blur} at scale {s} (σ \
                         {sigma:.2} device px) can reach"
                    ));
                    break;
                }
            }
            if let Some(why) = bad {
                out.push(
                    Finding::fail(
                        CheckId::Coherence,
                        format!(
                            "reach: shadow {x} {y} {blur} {spread} (offset, blur, spread): {why} \
                             (CSS box-shadow: a Gaussian of half its blur radius, every length \
                             times the scale)"
                        ),
                    )
                    .at(f.k)
                    .node(&sh.key)
                    .axis("shadow")
                    .in_segment(&seg_name(f.k)),
                );
            }
        }
    }
    super::stats("coherence.reach", cx, &[("shadows", judged)]);
    out
}
